-- Bronze-tabel: elk uur alleen nieuwe bestanden inlezen
CREATE OR REFRESH STREAMING TABLE bronze.demo.bestellingen_raw
  SCHEDULE EVERY 1 hour
  AS SELECT *
  FROM STREAM read_files(
    '/Volumes/bronze/demo/landing/bestellingen/',
    format => 'json'
  );

-- Met de hand verversen: alleen wat sinds de vorige keer binnenkwam
REFRESH STREAMING TABLE bronze.demo.bestellingen_raw;

-- Alles opnieuw verwerken met de huidige definitie (let op bij bronnen met korte bewaartijd)
REFRESH STREAMING TABLE bronze.demo.bestellingen_raw FULL;
